SELECT AVG(order_total) AS average_order_value
FROM (
  SELECT order_id, SUM(sale_price) AS order_total
  FROM `bigquery-public-data.thelook_ecommerce.order_items`
  GROUP BY order_id
);

SELECT AVG(total_spent) AS average_customer_spend
FROM (
  SELECT user_id, SUM(sale_price) AS total_spent
  FROM `bigquery-public-data.thelook_ecommerce.order_items`
  GROUP BY user_id
) t;

SELECT
  SAFE_DIVIDE(COUNTIF(status = 'Returned'), COUNT(*)) AS overall_return_rate
FROM `bigquery-public-data.thelook_ecommerce.orders`;

SELECT
  SUM(CASE WHEN status = 'Returned' THEN sale_price ELSE 0 END) AS revenue_lost_to_returns
FROM `bigquery-public-data.thelook_ecommerce.order_items`;
